# -*- coding: utf-8 -*-
from part1 import M, add

add(21, "ดาวจันทร์กับดาวอาทิตย์", "เลขที่ส่งเสริมเสน่ห์และการเข้าสังคม เป็นคนเด่นที่มีผู้ยกย่อง ภายนอกดูอ่อนแอนุ่มนวล แต่ภายในแข็งกล้าและตัดสินใจได้เด็ดขาดจนคนอื่นคาดไม่ถึง",
    "มีเสน่ห์ เข้าสังคมได้ดี ได้รับเกียรติ ซ่อนบุคลิกที่แท้จริงได้แนบเนียน", "ชีวิตมักมีจุดหักเหกลางคัน เกิดเรื่องไม่คาดฝันที่ทำให้ต้องเปลี่ยนทางเดิน อนาคตไม่ค่อยแน่นอน")
add(22, "ดาวจันทร์สองดวง", "เลขของนักคิดนักฝันที่อารมณ์อ่อนไหว มากด้วยจินตนาการมากกว่าการลงมือปฏิบัติ เชื่อใจคนง่าย และเมื่อปักใจแล้วมักดื้อรั้น",
    "จินตนาการสูง ละเอียดอ่อน", "หูเบา ถูกหลอกลวงหรือหักหลังง่าย ชอบสร้างวิมานในอากาศ ควรรอบคอบก่อนตัดสินใจทุกเรื่องและระวังการหลงเชื่อเรื่องไสยศาสตร์ ตำราว่าเป็นเลขที่ตัดสินใจผิดพลาดทั้งที่รู้")
add(23, "ดาวจันทร์กับดาวอังคาร", "เลขที่เด่นเรื่องความรักและอารมณ์ ภายนอกนุ่มนวลแต่ภายในแข็งกร้าว ไม่ยอมแพ้ใคร และมีเสน่ห์แรง ถ้ามีดาวดีมาเสริมจะหันไปทางดี ใฝ่หาความรู้ มีจิตใจเป็นกุศล และได้รับความช่วยเหลือจากผู้มีอำนาจ",
    "ใฝ่รู้ ได้รับความเกื้อกูลจากผู้ใหญ่ ประสบความสำเร็จได้ดี ถ้าเป็นสตรีมักมีผู้ใหญ่สนับสนุน", "เรื่องความรักอาจมีข่าวฉาวหรือปัญหา ถ้าเป็นชายควรระวังเรื่องหญิง คู่ครองอาจทำให้ตกต่ำหรือตกจากตำแหน่ง และมีศัตรูแอบทำร้ายเบื้องหลัง")
add(24, "ดาวจันทร์กับดาวพุธ", "เลขของคนที่มีเพื่อนมาก มารยาทเรียบร้อยนุ่มนวล เป็นที่รัก สติปัญญาว่องไว มีเสน่ห์ หยั่งรู้สถานการณ์ได้เร็ว และมักมีโชคลาภหรือความช่วยเหลือจากผู้อื่น",
    "ฉลาด ละเอียดอ่อน มีเสน่ห์ มิตรสหายอุปถัมภ์ ไม่ชอบแสดงอำนาจ เข้าถึงอารมณ์ศิลปะได้ง่าย", "ไม่ค่อยมีข้อเสียเด่นตามตำรา ควรรักษาความละเอียดอ่อนไว้ไม่ให้เปราะบางเกินไป",
    "ศิลปิน นักการค้า งานธุรกิจและงานที่ใช้ปัญญา")
add(25, "ดาวจันทร์กับดาวพฤหัสบดี", "เลขที่ดูเผินเป็นเลขดี เพราะเป็นดาวดีทั้งคู่ แต่กว่าจะสำเร็จต้องผ่านการต่อสู้อุปสรรคอย่างเหน็ดเหนื่อย ต้องอาศัยความหมั่นเพียรและอดทน",
    "ถ้าอดทนจะประสบความสำเร็จแน่นอน ได้คู่ครองที่ดี มีหลักฐาน มีความรู้ และผู้ใหญ่ช่วยเหลือ", "ชีวิตขึ้นลงไม่แน่นอน อาจถูกศัตรูปองร้ายหรือกลั่นแกล้ง ธาตุน้ำกับธาตุไฟไม่ถูกกัน จึงมักมีการเปลี่ยนแปลงบ่อย")
add(26, "ดาวจันทร์กับดาวศุกร์", "เลขของคนที่มีรสนิยมสูง มารยาทนุ่มนวล มีอารมณ์ทางศิลปะ ความสำเร็จมักมาแต่ไม่ยั่งยืนถาวร",
    "ละเอียดอ่อน มีรสนิยม มารยาทดี", "มักวิตกกังวลและถูกกดดันจากผู้มีอิทธิพล ต้องเลือกคบเพื่อนและหุ้นส่วนให้ดี เพราะเพื่อนอาจนำความเสียหายมาให้ ควรหลีกเลี่ยงการลุ่มหลงตามอารมณ์ ไม่เช่นนั้นอาจพบความโศกเศร้ารุนแรง")
add(27, "ดาวจันทร์กับดาวเสาร์", "เลขที่รวมกันได้ 9 ซึ่งตำราว่าบันดาลความสำเร็จอย่างงดงาม มีความคิดเป็นของตนเอง ดำเนินชีวิตรัดกุม แต่ก็แฝงความกดดันและความเศร้า",
    "ความคิดเป็นของตนเอง วางแผนชีวิตรัดกุม มีแนวโน้มโชคดีในอนาคต", "เอาจริงเอาจังกับชีวิตมากเกินไป มักมีโรคประจำตัวหรือความเจ็บป่วยเรื้อรัง ผิดหวังจากสตรี อาจสูญเสียบิดาหรือคู่ครองในช่วงที่ชีวิตกำลังรุ่งเรือง และควรระวังการผ่าตัดกับอุบัติเหตุ")
add(28, "ดาวจันทร์กับดาวราหู", "เลขที่ตำราว่าให้ผลเสียมากกว่าดี เป็นคนกล้าได้กล้าเสีย ชอบงานใหญ่ ชอบของใหม่ ไม่ชอบอยู่กับที่ ชอบไปเสี่ยงโชคในต่างแดน",
    "มั่นใจในตัวเอง กล้าคิดกล้าทำ ชอบสิ่งใหม่ ๆ", "ชอบเริ่มแต่ไม่ชอบรับผิดชอบ ชีวิตเต็มไปด้วยความขัดแย้งและมีเรื่องทุกข์ใจแอบแฝง อาจมีคนนินทา ผิดหวังเรื่องความรัก หรือต้องพลัดพรากจากมารดา")
add(29, "ดาวจันทร์กับดาวเกตุ", "เลขที่คล้ายเลข 28 บ่งถึงแรงกดดันและอิทธิพลเร้นลับ จิตใจเข้มแข็ง ภายนอกสดใสแต่ภายในอาจอมทุกข์ ตำราว่าเป็นลางบอกเหตุให้ระวัง",
    "จิตใจเข้มแข็ง", "ชีวิตมักหักกลางคัน ถูกศัตรูปองร้ายหรือโค่นอำนาจ ถูกหลอกลวง เพื่อนอาจไม่ซื่อสัตย์ ควรระวังอุบัติเหตุ สุขภาพ และเพศตรงข้าม ไม่ควรประมาทเรื่องอนาคต")
add(30, "ดาวอังคารกับดาวมฤตยู", "เลขของคนที่ไม่หยุดนิ่ง ชีวิตอาจรุ่งโรจน์ผาดโผน แต่ก็อาจล้มลงอย่างฉับพลัน ตำราว่าเป็นดาวคู่แห่งอุบัติเหตุ",
    "มีพลัง ทำงานรุ่งโรจน์ได้รวดเร็ว", "ระวังอุบัติเหตุ การผ่าตัด และความเจ็บป่วยกะทันหัน กิจการที่กำลังไปได้ดีอาจติดขัดทันที ไม่ควรประมาท")
add(31, "ดาวอังคารกับดาวอาทิตย์", "เลขที่น้ำกับไฟไม่ถูกกัน ตำราว่ามักโชคร้ายตอนต้นแล้วประสบความสำเร็จในบั้นปลาย ทำอะไรมักไม่ราบรื่น มีอุปสรรคมาขวางอยู่เสมอ",
    "ความสำเร็จมาในบั้นปลาย", "ระวังอุบัติเหตุ การผ่าตัด การถูกแย่งตำแหน่งงาน ความสัมพันธ์ของคู่ครองอาจหักกลางคัน ควรรอบคอบและรักษาความสมดุลในการทำสิ่งต่าง ๆ")
add(32, "ดาวอังคารกับดาวจันทร์", "เลขของคนมีเสน่ห์แรง เรื่องความสัมพันธ์ระหว่างเพศดีมาก ยึดมั่นในอุดมการณ์ ตำราว่าต้นร้ายปลายดี และมักมีผู้ใหญ่อุปถัมภ์อยู่เสมอ",
    "เสน่ห์แรง ยึดมั่นอุดมการณ์ มีผู้ใหญ่อุปถัมภ์ ปลายดี", "ทำงานต้องลงมือเองจึงจะสำเร็จ ระวังอุบัติเหตุและโรคเรื้อรังที่หายช้า ถ้าเป็นชายควรระวังหญิงที่อาจนำความทุกข์มาให้ มักกำพร้ามารดา")
add(33, "ดาวอังคารสองดวง", "เลขที่ตำราว่าน่ากลัวเพราะแรงมาก เหมือนแม่น้ำหลายสายรวมกันเป็นแม่น้ำใหญ่ อารมณ์ฉุนเฉียว ร้อนแรง เอาแต่ใจ และดื้อดึงจนหัวชนฝา",
    "มีพลังสูง ลุยจริง", "อุบัติเหตุมักมาเป็นสองเท่าและเกิดฉับพลัน โดยเฉพาะเรื่องความเร็ว มักทะเลาะวิวาท และมีอารมณ์ทางโลกีย์รุนแรง ควรควบคุมอารมณ์และความเร็ว")
add(34, "ดาวอังคารกับดาวพุธ", "เลขของคนมีสติปัญญาแตกฉาน ปฏิภาณดี กล้าทำกล้าพูด เปิดเผย ไม่ย่อท้อแม้เจออุปสรรคมาก และเอาตัวรอดได้ด้วยปัญญา",
    "ฉลาด กล้าหาญ ตรงไปตรงมา ไม่ท้อ", "ตอนเด็กมักเกิดอุบัติเหตุ หรือบาดเจ็บจากสัตว์และของมีคม ควรระวังโรคประสาทหรือเรื่องสมอง")
add(35, "ดาวอังคารกับดาวพฤหัสบดี", "เลขที่ต้องระวังเรื่องผู้ใหญ่และผู้ปกครอง มักต้องอาศัยผู้ใหญ่คอยเชิดชู แต่ให้ความคล่องแคล่ว พรสวรรค์ และเข้ากับคนได้ทุกระดับ บั้นปลายประสบความสำเร็จ",
    "คล่องแคล่ว มีพรสวรรค์ มีผู้ใหญ่อุปถัมภ์ บั้นปลายดี", "หูเบา เชื่อใจคนง่าย หลงผิดได้ ซึ่งอาจทำให้เสียอนาคต ตำราแนะนำว่าหลีกเลี่ยงได้ก็ควรหลีกเลี่ยง")
add(36, "ดาวอังคารกับดาวศุกร์", "เลขของความรักและความสดชื่น มีมิตรสหายมาก เพศตรงข้ามให้ความอบอุ่น ชีวิตวัยหนุ่มสาวมีความรักโลดโผน ตำราถือเป็นเลขให้คุณ",
    "ชีวิตรักดี มีมิตรมาก สดชื่น ประสบความสำเร็จ", "เจ้าอารมณ์ มีความคิดเห็นรุนแรง")
add(37, "ดาวอังคารกับดาวเสาร์", "เลขที่ตำราถือว่าร้าย เป็นดาวบาปเคราะห์ทั้งคู่ ชีวิตขึ้น ๆ ลง ๆ ไม่ราบรื่น มีจุดหักเหตลอดเวลา",
    "", "ระวังการทะเลาะวิวาท โรคร้ายและโรคประจำตัว การผ่าตัด อุบัติเหตุ และความเสียหายที่มาอย่างรวดเร็ว ตำราแนะนำให้เปลี่ยนชื่อหากผลรวมของชื่อ-นามสกุลได้เลขนี้")
add(38, "ดาวอังคารกับดาวราหู", "เลขของอำนาจและความหลงมัวเมา ชอบใช้อารมณ์ ชอบถืออำนาจ ชอบคบคนหมู่มาก และชีวิตมักเปลี่ยนแปลงรุนแรง",
    "มีบารมีกับคนหมู่มาก", "หลงงมงาย เชื่อเรื่องวิญญาณและการทรงเจ้าเข้าผีมากจนถอนตัวยาก ควรเลือกคบเพื่อนและระวังการใช้อารมณ์")
add(39, "ดาวอังคารกับดาวเกตุ", "เลขกลาง ๆ ที่ตำราว่ามักทำให้พบความยุ่งยากในชีวิตอยู่บ่อย ๆ มีความกดดันสูงและกระทบกระเทือนใจรุนแรง",
    "", "ควรระวังความกดดันและความผิดปกติทางอารมณ์ รวมทั้งระวังบุคคลที่สามเข้ามาเกี่ยวข้อง")
add(40, "ดาวพุธกับดาวมฤตยู", "เลขของคนที่ชอบสิ่งแปลกใหม่ เพ้อฝันถึงสิ่งเร้นลับและสิ่งมหัศจรรย์ มีรสนิยมแปลก ชอบสร้างความประหลาดใจ และชอบคิดค้นของใหม่ ๆ ให้ผู้อื่น",
    "คิดค้นเก่ง สร้างสรรค์ มีความคิดแปลกใหม่", "เชื่อใจคนง่าย อยู่ไม่เป็นที่ ชอบเปลี่ยนที่นั่งหรือที่อยู่ ต้องเดินทางบ่อย")
add(41, "ดาวพุธกับดาวอาทิตย์", "เลขที่อยู่ร่วมกันได้ดี ปัญญาเป็นดาวพุธ ความเป็นผู้นำเป็นดาวอาทิตย์ มีสมองปราดเปรื่องตั้งแต่เด็ก ทะเยอทะยาน เข้ากับมิตรสหายดี และมีผู้ใหญ่อุปถัมภ์",
    "ฉลาด ทะเยอทะยาน เข้ากับคนง่าย เก็บความรู้สึกเก่ง ประสบความสำเร็จดีเยี่ยม", "ไม่ค่อยมีข้อเสียเด่นตามตำรา ควรระวังการเก็บความรู้สึกไว้มากเกินไป")
add(42, "ดาวพุธกับดาวจันทร์", "เลขของคนละเอียดอ่อน ชอบศิลปะ กวี และเสียงเพลง ใจละมุน สมองแจ่มใส มีหัวด้านประดิษฐ์ คิดค้น และงานเขียน เป็นที่รักของเพื่อนฝูง",
    "ศิลปะดี ใจละเอียดอ่อน คิดสร้างสรรค์ มีมิตรช่วยเหลือ ประสบความสำเร็จดี", "ค่อนข้างเพ้อฝันและอ่อนไหวบอบบาง",
    "นักประพันธ์ นักประดิษฐ์ ศิลปิน งานที่ใช้ความคิดและงานเบา ๆ")
